# Counted work: each statement reads only the stored rows its answer needs, whatever the size of
# the table; `# reads N` says how many. `t` row n is (n, 'row-<n>', n % 400), indexed by tag and by
# name; event n is (n, 'k<n % 400>', n, 'note-<n>'), indexed by kind and then seq descending. A
# thousand rows each, so that a path that reads the whole table shows.
CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT NOT NULL, tag INTEGER NOT NULL, UNIQUE (name));
CREATE INDEX t_tag ON t (tag);
CREATE INDEX t_name ON t (name);
CREATE TABLE events (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, seq INTEGER NOT NULL, note TEXT);
CREATE INDEX events_kind_seq ON events (kind ASC, seq DESC);
