# A key reads its one row (reads 1), a key that is not there none (reads 0), and a key taken from
# a SELECT the row in each table (reads 2).
SELECT id, name, tag FROM t WHERE id = 500;
----
id | name | tag  (read 1, compared 0)
500 | row-0000500 | 100

SELECT id FROM t WHERE id = 5000;
----
id  (read 0, compared 0)

SELECT id FROM t WHERE id IN (SELECT id FROM events WHERE id = 5);
----
id  (read 2, compared 0)
5

# Through an index of one column, the 3 rows of a tag (reads 3); of two, by its first column
# (reads 3), by both (reads 1), and the newest of a kind, its first entry for the kind (reads 1).
SELECT id FROM t WHERE tag = 3 ORDER BY id;
----
id  (read 3, compared 0)
3
403
803

SELECT id FROM events WHERE kind = 'k2' ORDER BY id;
----
id  (read 3, compared 0)
2
402
802

SELECT id, note FROM events WHERE kind = 'k2' AND seq = 402;
----
id | note  (read 1, compared 0)
402 | note-402

SELECT id FROM events WHERE kind = 'k2' ORDER BY seq DESC LIMIT 1;
----
id  (read 1, compared 0)
802

# A sort an index gives reads only the limit: by the key, by an indexed column, and within one
# kind by the second column of an index (reads 2 each). An order no index gives reads all 1,000.
SELECT id FROM t ORDER BY id LIMIT 2;
----
id  (read 2, compared 0)
1
2

SELECT id FROM t ORDER BY name LIMIT 2;
----
id  (read 2, compared 0)
1
2

SELECT id FROM events WHERE kind = 'k2' ORDER BY seq DESC LIMIT 2;
----
id  (read 2, compared 0)
802
402

SELECT id FROM events ORDER BY seq LIMIT 2;
----
id  (read 1000, compared 0)
1
2

# A negative number narrows as a positive one does. Row n has the number n % 4 - 1: a search of
# one partition of pending vectors reads its 4 rows and the 2 it returns once more (reads 6), and
# a lookup through the index reads its 4 rows (reads 4).
CREATE TABLE marks (id INTEGER PRIMARY KEY, kind INTEGER NOT NULL, v VECTOR(2) PARTITION_KEY (kind));
CREATE TABLE plain (id INTEGER PRIMARY KEY, k INTEGER NOT NULL);
CREATE INDEX plain_k ON plain (k);
