# A repeated statement answers as the store is now, whatever was planned for its text before: with
# the index it read through dropped it reads every row (reads 16), with the index made again its
# 4 rows; it sees a column added after it first ran, and a dropped table is missing.
DROP INDEX plain_k ON plain;
SELECT id FROM plain WHERE k = -1 ORDER BY id;
----
id  (read 16, compared 0)
4
8
12
16

CREATE INDEX plain_k ON plain (k);
SELECT id FROM plain WHERE k = -1 ORDER BY id;
----
id  (read 4, compared 0)
4
8
12
16

SELECT * FROM plain WHERE id = 4;
----
id | k  (read 1, compared 0)
4 | -1

ALTER TABLE plain ADD COLUMN note TEXT DEFAULT 'none';
SELECT * FROM plain WHERE id = 4;
----
id | k | note  (read 1, compared 0)
4 | -1 | none

DROP TABLE plain;
SELECT * FROM plain WHERE id = 4;
----
